import { z } from 'zod';
import { defineCommand } from '../../kernel/index.ts';
import { orgPermissions } from '../permissions.ts';

export const createSite = defineCommand({
  name: 'org.site.create',
  permission: orgPermissions.createSite,
  input: z.object({ id: z.uuid() }),
  describe: (i) => `Create a project/site; generates its Project ID ${i.id}`,
  handle: (_ctx, i) =>
    Promise.resolve({
      result: { id: i.id },
      audit: { objectType: 'site', objectId: i.id, clientId: null, before: null, after: null },
    }),
});
